package controlador;
import dao.LibroDAO;import dao.PrestamoDAO;import modelo.Prestamo;import java.sql.SQLException;import java.util.List;
public class PrestamoController {private final LibroDAO libros=new LibroDAO();private final PrestamoDAO prestamos=new PrestamoDAO();public void prestar(int libro,int estudiante)throws SQLException{if(libro<=0||estudiante<=0)throw new IllegalArgumentException("Selecciona estudiante y libro.");libros.prestar(libro,estudiante);}public void devolver(int id)throws SQLException{prestamos.devolver(id);}public List<Prestamo> listar()throws SQLException{return prestamos.listar();}public List<Object[]> masPrestados()throws SQLException{return prestamos.masPrestados();}public List<Object[]> historial()throws SQLException{return prestamos.historial();}public List<Object[]> pendientes()throws SQLException{return prestamos.pendientes();}}